/*
 * A226080  Denominators in the Fibonacci (or rabbit) ordering of the positive
 *          rational numbers.
 * https://oeis.org/A226080
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, frac
 * Formula:   a(n) = denominator of the n-th rational in the rabbit ordering
 *            of positive rationals generated by x → {x+1, 1/x}
 * Range:     u8 n <= 6000, u16 n <= 6000, u32 n <= 6000, u64 n <= 6000,
 *            u128 n <= 6000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Rational number representation */
typedef struct {
    seq_t num;
    seq_t den;
} rational_t;

/* Global state: arrays for denominators, visited rationals, and
   generation indices.  All allocated lazily and expanded only as
   needed.  The structures are kept static so that repeated calls to
   a() can reuse them. */
static seq_t  *denoms   = NULL;   /* denominators in order of appearance   */
static size_t  denoms_len = 0;
static size_t  denoms_cap = 0;

static rational_t *rats   = NULL; /* all distinct rationals seen so far   */
static size_t     rats_len  = 0;
static size_t     rats_cap  = 0;

static size_t *gen_cur   = NULL; /* indices of current generation      */
static size_t *gen_next  = NULL; /* indices of next generation         */
static size_t   gen_cur_len   = 0;
static size_t   gen_next_len  = 0;
static size_t   gen_cap       = 0;

/* Utility: ensure capacity for a seq_t array. */
static void ensure_denoms_cap(size_t needed)
{
    if (denoms_cap < needed) {
        size_t new_cap = denoms_cap ? denoms_cap * 2 : 16;
        if (new_cap < needed) new_cap = needed;
        denoms = (seq_t *)realloc(denoms, new_cap * sizeof(seq_t));
        denoms_cap = new_cap;
    }
}

/* Utility: ensure capacity for a rational_t array. */
static void ensure_rats_cap(size_t needed)
{
    if (rats_cap < needed) {
        size_t new_cap = rats_cap ? rats_cap * 2 : 16;
        if (new_cap < needed) new_cap = needed;
        rats = (rational_t *)realloc(rats, new_cap * sizeof(rational_t));
        rats_cap = new_cap;
    }
}

/* Utility: ensure capacity for a size_t index array. */
static void ensure_gen_cap(size_t needed)
{
    if (gen_cap < needed) {
        size_t new_cap = gen_cap ? gen_cap * 2 : 16;
        if (new_cap < needed) new_cap = needed;
        gen_cur  = (size_t *)realloc(gen_cur,  new_cap * sizeof(size_t));
        gen_next = (size_t *)realloc(gen_next, new_cap * sizeof(size_t));
        gen_cap  = new_cap;
    }
}

/* Check whether a rational (num,den) has already been seen. */
static int contains_exact(const seq_t *num, const seq_t *den)
{
    for (size_t i = 0; i < rats_len; ++i) {
        if (rats[i].num == *num && rats[i].den == *den)
            return 1;
    }
    return 0;
}

/* Generate terms until we have at least n denominators. */
static void generate_up_to(idx_t n)
{
    /* Lazily initialize state on first call. */
    if (rats == NULL) {
        ensure_rats_cap(16);
        rats[0].num = (seq_t)1;
        rats[0].den = (seq_t)1;
        rats_len = 1;

        ensure_denoms_cap(16);
        denoms[0] = (seq_t)1;
        denoms_len = 1;

        ensure_gen_cap(16);
        gen_cur[0] = 0;
        gen_cur_len = 1;
    }

    while ((idx_t)denoms_len < n) {
        gen_next_len = 0;

        for (size_t gi = 0; gi < gen_cur_len; ++gi) {
            const rational_t r = rats[gen_cur[gi]];

            /* Child 1: r + 1  ->  (num + den)/den */
            seq_t new_num = r.num + r.den;
            seq_t new_den = r.den;
            if (!contains_exact(&new_num, &new_den)) {
                ensure_rats_cap(rats_len + 1);
                rats[rats_len].num = new_num;
                rats[rats_len].den = new_den;

                ensure_denoms_cap(denoms_len + 1);
                denoms[denoms_len++] = new_den;

                ensure_gen_cap(gen_next_len + 1);
                gen_next[gen_next_len++] = rats_len++;
            }

            /* Child 2: 1/r  ->  den/num */
            new_num = r.den;
            new_den = r.num;
            if (!contains_exact(&new_num, &new_den)) {
                ensure_rats_cap(rats_len + 1);
                rats[rats_len].num = new_num;
                rats[rats_len].den = new_den;

                ensure_denoms_cap(denoms_len + 1);
                denoms[denoms_len++] = new_den;

                ensure_gen_cap(gen_next_len + 1);
                gen_next[gen_next_len++] = rats_len++;
            }
        }

        /* Advance to the next generation. */
        size_t *tmp = gen_cur;
        gen_cur = gen_next;
        gen_next = tmp;

        size_t tl = gen_cur_len;
        gen_cur_len = gen_next_len;
        gen_next_len = tl;
    }
}

/* ------------------------------------------------------------ */
/* exported routine */

seq_t a(idx_t n)
{
    generate_up_to(n);
    return denoms[(size_t)(n - 1)];
}
